// Site builder: run `node tools/site.js` from the project root after adding or changing pages.
// 1. Adds (or refreshes) the subject tabs in the top bar of every page.
// 2. Regenerates subject hub pages that were generated by this script (marked <!-- generated-hub -->).
//    Hand-made hubs (physics/index.html, business/index.html) are kept; only their tabs are refreshed.
// 3. Regenerates the home page index.html listing every subject and page.
const fs = require("fs"), path = require("path");
const ROOT = path.join(__dirname, "..");
const SUBJECTS = [
  ["physics", "Physics", "Forces, waves, electricity and modern physics."],
  ["business", "Business", "Stakeholders, enterprise, leadership and informed decisions."],
  ["maths", "Maths", "Statistics and probability, geometry, number, algebra and functions."],
  ["applied-maths", "Applied Maths", "Modelling, networks, mechanics and a changing world."],
  ["english", "English", "Single text, comparative study, poetry and Paper 1."],
  ["spanish", "Spanish", "Communication, language awareness and culture."],
  ["irish", "Irish", "Gaeilge: topics for the oral, writing, prose and poetry."],
];
const START = "<!--subj-nav-->", END = "<!--/subj-nav-->";
const CSS = `${START}<style id="subj-css">
.subj{display:flex;gap:4px;align-items:center;overflow-x:auto;scrollbar-width:none;max-width:100%;min-width:0;margin-right:auto}
.subj::-webkit-scrollbar{display:none}
.subj a{white-space:nowrap;text-decoration:none;color:var(--muted);font-weight:700;font-size:.86rem;padding:6px 12px;border-radius:999px;border:1.5px solid transparent}
.subj a:hover{color:var(--ink);background:var(--surface-2)}
.subj a.on{color:var(--ink);background:color-mix(in srgb,var(--terra) 16%,transparent);border-color:color-mix(in srgb,var(--terra) 40%,transparent)}
@media (max-width:1180px){.subj{order:3;flex-basis:100%;margin-right:0}}
</style>${END}`;
const nav = (cur, prefix) => `${START}<nav class="subj" aria-label="Subjects"><a href="${prefix}index.html"${cur==="home"?' class="on" aria-current="page"':""}>Home</a>${SUBJECTS.map(([id,name])=>`<a href="${prefix}${id}/index.html"${cur===id?' class="on" aria-current="page"':""}>${name}</a>`).join("")}</nav>${END}`;
// Remove each marked block plus the line break (and indentation) we added after it, so reruns don't add blank lines.
const strip = h => h.split(START).map((part,i)=> i===0? part : part.slice(part.indexOf(END)+END.length).replace(/^\r?\n[ \t]*/,"")).join("");
function inject(file, cur, prefix){
  let h = strip(fs.readFileSync(file,"utf8"));
  if(!h.includes('<div class="tools">')) { console.warn("no tools div:", file); return; }
  h = h.replace('<div class="tools">', nav(cur,prefix)+'\n      <div class="tools">');
  h = /<header class="top"/.test(h) ? h.replace(/<header class="top"/, CSS+'\n<header class="top"') : h.replace('<div class="tools">', CSS+'<div class="tools">');
  fs.writeFileSync(file, h);
}
const head = title => fs.readFileSync(path.join(ROOT,"physics","refraction-lenses.html"),"utf8").split("</style>")[0].replace(/<title>[^<]*<\/title>/, `<title>${title}</title>`) + "</style>";
const esc = s => s.replace(/&(?!amp;|lt;|gt;|#)/g,"&amp;");
function pageInfo(dir, f){ const h=fs.readFileSync(path.join(dir,f),"utf8"); const b=h.match(/<div class="brand">[\s\S]*?<b>([\s\S]*?)<\/b><span>([\s\S]*?)<\/span>/);
  return { f, title: b? b[1] : (h.match(/<title>([^<]*)<\/title>/)||[,f])[1], sub: b? b[2] : "" }; }
const pagesOf = id => { const dir=path.join(ROOT,id); return fs.readdirSync(dir).filter(f=>f.endsWith(".html") && f!=="index.html" && !f.includes(".draft.")).sort().map(f=>pageInfo(dir,f)); };
const THEME_JS = `<script>(()=>{const r=document.documentElement,k="site-theme";let t="auto";try{t=localStorage.getItem(k)||"auto"}catch(e){}const a=()=>{if(t==="auto")r.removeAttribute("data-theme");else r.setAttribute("data-theme",t);const l=document.getElementById("themeLbl");if(l)l.textContent=t==="auto"?"Auto":t==="light"?"Light":"Dark"};a();document.getElementById("themeBtn").addEventListener("click",()=>{t=t==="auto"?"light":t==="light"?"dark":"auto";try{localStorage.setItem(k,t)}catch(e){}a()})})();</script>`;
function shell(title, brandB, brandS, cur, prefix, body){
  return `${head(title)}
${CSS}
<header class="top"><div class="gut"><div class="brandrow" style="max-width:1360px;margin:0 auto">
  <div class="brand"><div class="logo" aria-hidden="true"><svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 5a2 2 0 012-2h13v16H6a2 2 0 00-2 2z"/><path d="M4 19V5"/></svg></div><div style="min-width:0"><b>${brandB}</b><span>${brandS}</span></div></div>
  ${nav(cur,prefix)}
  <div class="tools"><button id="themeBtn" class="ghost" aria-label="Change colour theme" title="Theme">◐ <span id="themeLbl">Auto</span></button></div>
</div></div></header>
<div class="gut"><main style="max-width:1360px;margin:0 auto;padding-block:24px;display:grid;gap:22px">
${body}
</main></div>
${THEME_JS}
`;
}
const card = (href, title, sub, extra="") => `<a class="panel tcard" href="${href}" style="text-decoration:none;color:inherit;display:grid;gap:6px;padding:18px"><h3>${title}</h3><p style="color:var(--muted)">${sub}</p>${extra}<span class="pill t" style="justify-self:start">Open →</span></a>`;
// 1–2. subject pages and hubs
for(const [id,name,blurb] of SUBJECTS){
  const dir=path.join(ROOT,id); if(!fs.existsSync(dir)) continue;
  const hub=path.join(dir,"index.html"), pages=pagesOf(id);
  const generated = !fs.existsSync(hub) || fs.readFileSync(hub,"utf8").includes("<!-- generated-hub -->");
  if(generated){
    const body = `<!-- generated-hub -->
<section class="hero" style="grid-template-columns:1fr"><div><span class="pill t">Leaving Cert ${name}</span><h1 style="margin-top:12px">${name}</h1><p class="lede">${blurb} ${pages.length? `${pages.length} interactive page${pages.length===1?"":"s"} so far; more are added every week.` : "The first chapter is on its way."}</p></div></section>
${pages.length? `<div class="topics">${pages.map(p=>card(p.f, p.title, p.sub)).join("\n")}</div>` : `<div class="panel pad"><p>No pages yet. Check back soon.</p></div>`}`;
    fs.writeFileSync(hub, shell(`${name} · Leaving Cert`, `Leaving Cert ${name}`, "Interactive study pages", id, "../", body));
  }
  for(const f of fs.readdirSync(dir).filter(f=>f.endsWith(".html"))) inject(path.join(dir,f), id, "../");
}
// 3. home page
const homeBody = `<section class="hero" style="grid-template-columns:1fr"><div><span class="pill t">Free · Interactive · Leaving Certificate</span><h1 style="margin-top:12px">Study the Leaving Cert<br><em>by doing, not just reading.</em></h1><p class="lede">Visual notes, labs and simulations, flashcards, quizzes and exam practice for each topic, built from the official specifications and syllabuses. Pick a subject.</p></div></section>
<div class="topics">${SUBJECTS.filter(([id])=>fs.existsSync(path.join(ROOT,id))).map(([id,name,blurb])=>{ const ps=pagesOf(id); return card(`${id}/index.html`, name, blurb, ps.length? `<p style="font-size:.88rem"><b>${ps.length}</b> page${ps.length===1?"":"s"}: ${ps.slice(0,4).map(p=>p.title).join(" · ")}${ps.length>4?" …":""}</p>` : `<p style="font-size:.88rem">Coming soon</p>`); }).join("\n")}</div>
<p class="result">Practice questions on these pages are not official SEC papers. Scenarios and figures in labs are illustrative.</p>`;
fs.writeFileSync(path.join(ROOT,"index.html"), shell("Leaving Cert Study Lab", "Leaving Cert Study Lab", "All subjects", "home", "", homeBody));
console.log("site updated:", SUBJECTS.map(([id])=>`${id} ${fs.existsSync(path.join(ROOT,id))?pagesOf(id).length:0}`).join(", "));
